CREATE TABLE IF NOT EXISTS offers (id TEXT PRIMARY KEY,title TEXT NOT NULL,price REAL NOT NULL,original_price REAL,discount REAL NOT NULL DEFAULT 0,rating REAL,sales INTEGER,shop TEXT,image_url TEXT NOT NULL,destination TEXT NOT NULL,source TEXT NOT NULL,category TEXT,published_at INTEGER NOT NULL,coupon_code TEXT,coupon_condition TEXT,coupon_expires_at INTEGER,payment_label TEXT,cataloged_at INTEGER,last_checked_at INTEGER,last_seen_at INTEGER,availability TEXT NOT NULL DEFAULT 'active',refresh_failures INTEGER NOT NULL DEFAULT 0,price_changed_at INTEGER);
CREATE INDEX IF NOT EXISTS idx_offers_published ON offers(published_at DESC);
CREATE INDEX IF NOT EXISTS idx_offers_category_published ON offers(category,published_at DESC);
CREATE INDEX IF NOT EXISTS idx_offers_shop_published ON offers(shop,published_at DESC);
CREATE INDEX IF NOT EXISTS idx_offers_availability_checked ON offers(availability,last_checked_at);
CREATE INDEX IF NOT EXISTS idx_offers_cataloged ON offers(cataloged_at DESC);
CREATE TABLE IF NOT EXISTS clicks (offer_id TEXT NOT NULL,clicked_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_site_clicks_time ON clicks(clicked_at);
CREATE TABLE IF NOT EXISTS coupons (id TEXT PRIMARY KEY,source TEXT NOT NULL,code TEXT NOT NULL,title TEXT,kind TEXT NOT NULL DEFAULT 'code',condition TEXT,destination TEXT NOT NULL,active_at INTEGER,expires_at INTEGER,published_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_coupons_expires_published ON coupons(expires_at,published_at DESC);
CREATE TABLE IF NOT EXISTS store_links (slug TEXT PRIMARY KEY,name TEXT NOT NULL,destination TEXT NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS offer_prices (offer_id TEXT NOT NULL,observed_on TEXT NOT NULL,price REAL NOT NULL,observed_at INTEGER NOT NULL,PRIMARY KEY (offer_id,observed_on));
CREATE INDEX IF NOT EXISTS idx_offer_prices_offer_time ON offer_prices(offer_id,observed_at DESC);
CREATE TABLE IF NOT EXISTS offer_feedback (offer_id TEXT NOT NULL,kind TEXT NOT NULL,quantity INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL,PRIMARY KEY (offer_id,kind));
